#!/usr/bin/env node
// JR編 v6 「渋谷Halloweenには近づくな」 (next/CONTRACT.md, docs/V6.md): build web3d/shibuya/series/variants/jr/v6/<pair>.json
// and v6/_opening.json from the combined episode configs (variants/jr/combined/<pair>.json, themselves generated by
// tools/combined_configs.mjs) + the pinned opening config (_opening.json) + the re-shoot list (v6/_reshoot.json), so the
// configs are reproducible. Edit COPY / NEW beats / the re-shoot list here (or in _reshoot.json), re-run --write.
//   node tools/v6_configs.mjs [--write] [--check] [<pair> …]
//     (default) summary;  --write  write the configs;  --check  exit 1 when a file on disk differs (tests, render_v6.sh check)
//   node tools/v6_configs.mjs --import-reshoot <notes-env3d.md> [--write]
//     parse the RESHOOT markdown table (a table under a heading containing 'RESHOOT': | pair | beat | why | [shot params] |
//     [crowd params] | [header] |, pair = gate|taxi|zone|alt|all, beat = a copied v6 beat id; params cells = JSON objects or empty) and
//     write v6/_reshoot.json (with --write) — the integrator can also edit _reshoot.json by hand.
//
// v6 opening: op-fly / op-logo / op-press / rules = the pinned opening beats (reuse:{variant:'_opening'} → frames copied
// from the pinned opening.mp4), notice → a NEW `mission` beat (3.5 s, card-bg, HUD mission card).
// v6 body (19 beats, V6_BEATS): first-choice / true-end / guide (NEW) + the 14 copied combined beats + goodbye / sources (NEW).
// Copied beats are deep copies of the combined config's beats (already self-contained: shot.t0, crowd.t0+restart,
// clock HH:MM:SS, vt0, bgm/amb); the combined episode's own new beats (caught/over-stamp/continue/kaiju) additionally get
// an explicit shot.t0 + vt0 (= the combined video time), so every copied beat renders on its own exactly like its source.
// Reuse sources: over-* → '<pair>-over' body, clear-* → '<pair>-clear' body, except beats the combined episode re-shot
// (zone/alt clear-result + clear-stamp: origin there) → 'combined/<pair>'; caught/over-stamp/continue/kaiju → 'combined/<pair>'.
// Re-shoot: a beat listed in _reshoot.json gets origin (same source ref) instead of reuse (+ params patch + fix note).
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import * as V from '../web3d/shibuya/series/variant-system.mjs';
import {FACTS} from '../web3d/shibuya/series/sources-series.mjs';

const ROOT=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const DIR=path.join(ROOT,'web3d/shibuya/series/variants/jr');
export const OUTDIR=path.join(DIR,'v6');
export const PAIRS=['gate','taxi','zone','alt'];
export const RESHOOT_FILE=path.join(OUTDIR,'_reshoot.json');
const read=f=>JSON.parse(fs.readFileSync(path.join(DIR,f),'utf8'));
const clone=v=>JSON.parse(JSON.stringify(v));
const r4=v=>+(+v).toFixed(4);

// ---------------------------------------------------------------- copy (JA; CONTRACT.md — HUD props per next/notes-hud.md)
export const MISSION={c:'mission',card:true,issuer:'脱出ゲーム運営（架空）',ja:V.V6_MISSION.ja.join('\n'),en:V.V6_MISSION.en,factIds:[]};
export const FIRST_OPTIONS=[{key:'A',ja:V.V6_FIRST.A,factIds:[]},{key:'B',ja:V.V6_FIRST.B,sub:V.V6_FIRST.Bsub,factIds:[]}];
export const FIRST_PICK_AT=3.5;   // HUD default dur−1.0; ≥ 1 s of the picked 「そもそも渋谷に行かない」 before the cut
export const FIRST_CHOICE={c:'choice',card:true,prompt:{ja:V.V6_FIRST.prompt},en:'First, what will you do?',options:FIRST_OPTIONS,picked:'A',pickAt:FIRST_PICK_AT,factIds:[]};
export const TRUE_END={c:'stamp',kind:'TRUE_END',ja:'今年の渋谷ハロウィンには行かない',kicker:'いちばん安全なクリア',en:"TRUE END — the safest clear: don't go.",factIds:[]};
export const GUIDE={c:'guide',ja:'ここからは“もしも”の脱出ガイド',sub:'もう渋谷にいる人（仕事・住まい・うっかり来た人）へ',en:'From here: a just-in-case escape guide',
 options:FIRST_OPTIONS,hot:'B',doneKey:'A',doneLabel:'TRUE END',factIds:[]};
// GOODBYE BAD HALLOWEEN (verbatim, V6_GOODBYE; only line breaks added): block 1 = the city's text (quoted, attributed),
// block 2 = facts, block 3 = OUR message (team label, no attribution), footer = sources + fiction note
const G=V.V6_GOODBYE;
export const GOODBYE={c:'goodbye',
 quote:{title:G.quote.title,ja:G.quote.ja.replace('喫煙、','喫煙、\n'),attr:G.quote.attr,en:G.quote.en,enAttr:G.quote.enAttr,label:'引用'},
 facts:G.facts.map(f=>({ja:f.ja,en:f.en})),
 ours:{label:'制作チームより',ja:'いちばんのCLEARは、\n今年の渋谷に「行かない」こと。',en:G.ours.en},
 foot:{ja:G.foot.ja,en:G.foot.en},factIds:[]};
// end-card fact ids (factcheck owner adds them to sources-series.mjs FACTS; only ids that exist are listed in sources[])
export const ENDCARD_FACTS=['END-01','END-02','END-03'];   // factcheck: X post + ordinance (渋谷区) · Hachiko fence · traffic restrictions (notes-factcheck.md)
// QA v6 (qa-visual 4 / qa-rules 4): the HUD header sub 「10/31 渋谷からどう帰る？」 assumes the viewer is already in Shibuya;
// on the NEW concept beats (mission, first choice, TRUE END, guide, sources) it carries the v6 concept line instead. The
// reused run keeps the original header (it is the just-in-case guide for people already there).
export const HEADER_V6={sub:'10/31 渋谷ハロウィンには近づくな'};
// QA v6 (qa-visual 3 / qa-rules 1): the sources card comes right after the real, quoted city / police text — the note
// says the GAME is fiction and the quotes / dates are as published (no 「パロディ」 wording next to a real quote).
export const SOURCES_NOTE={ja:'※本編（ゲーム部分）はフィクションです。引用・日付は各出典の公表内容です',en:'*The game story is fiction; quotes and dates are as published by each source.'};
export const BGM={first:'calm',trueEnd:'calm',guide:'tension',goodbye:'farewell',sources:'farewell'};

// ---------------------------------------------------------------- re-shoot list (v6/_reshoot.json)
export function readReshoot(){return fs.existsSync(RESHOOT_FILE)?JSON.parse(fs.readFileSync(RESHOOT_FILE,'utf8')).items||[]:[];}
export const reshootFor=(pair,list=readReshoot())=>list.filter(r=>r.pair===pair||r.pair==='all');
// markdown → [{pair, beat, why, shot?, crowd?}] (the first table after a heading that contains RESHOOT)
export function parseReshootTable(md){const lines=md.split('\n');let i=lines.findIndex(l=>/^#+.*RESHOOT/i.test(l));if(i<0)return null;
 const rows=[];let head=null;
 for(i++;i<lines.length;i++){const l=lines[i].trim();if(/^#+\s/.test(l)&&head)break;if(!l.startsWith('|')){if(head&&rows.length)break;continue;}
  const cells=l.replace(/^\||\|$/g,'').split('|').map(c=>c.trim().replace(/^`|`$/g,''));
  if(!head){head=cells.map(c=>c.toLowerCase());continue;}if(cells.every(c=>/^:?-+:?$/.test(c)))continue;
  const col=k=>{const j=head.findIndex(h=>h.includes(k));return j>=0?cells[j]:'';};
  const pair=col('pair').toLowerCase(),beat=col('beat'),why=col('why')||col('reason');const js=k=>{const v=col(k);if(!v||v==='-'||v==='—')return null;try{return JSON.parse(v);}catch{throw Error(`RESHOOT row ${pair}/${beat}: ${k} is not JSON: ${v}`);}};
  for(const p of pair.split(/[,\s]+/).filter(Boolean)){if(![...PAIRS,'all'].includes(p))throw Error(`RESHOOT row: unknown pair ${p}`);
   for(const b of beat.split(/[,\s]+/).filter(Boolean)){if(!V.V6_COPIED.includes(b))throw Error(`RESHOOT row: ${b} is not a copied v6 beat (${V.V6_COPIED.join(', ')})`);
    const r={pair:p,beat:b,why};const sp=js('shot'),cp=js('crowd'),hp=js('header');if(sp)r.shot=sp;if(cp)r.crowd=cp;if(hp)r.header=hp;rows.push(r);}}}
 return rows;}

// ---------------------------------------------------------------- build
export function buildOpening(op=read('_opening.json')){
 const beats=[];for(const b of op.beats){
  if(b.id==='notice'){beats.push({id:'mission',dur:3.5,shot:{key:'card-bg'},hud:[clone(MISSION)],header:clone(HEADER_V6)});continue;}
  beats.push({...clone(b),reuse:{variant:'_opening',beat:b.id}});}
 return {id:'_opening-v6',episode:'jr',part:'opening',edition:'v6',beats,bgm:op.bgm,amb:op.amb,
  generated:'tools/v6_configs.mjs (do not edit by hand: edit the generator and re-run --write)'};}

export function buildV6(pair,{reshoot=readReshoot()}={}){
 const K=read(`combined/${pair}.json`),KP=V.buildPart(K,'body'),kid=`combined/${pair}`;
 const opDur=V.buildPart(read('_opening.json'),'opening').duration;   // the combined episode's (pinned) opening
 const RS=reshootFor(pair,reshoot);
 const copied=V.V6_COPIED.map(id=>{const kb=KP.beats.find(b=>b.id===id),b=clone(K.beats[kb.index]);
  const src=V.v6Source(id);let ref;
  if(src[0]==='combined'||b.origin)ref={variant:kid,beat:id};          // rendered by the combined episode (new or re-shot)
  else ref={...b.reuse};                                               // the variant body the combined episode copied
  delete b.reuse;delete b.origin;delete b.fix;
  if(b.shot&&b.shot.t0==null)b.shot.t0=r4(kb.shotOffset);
  if(b.vt0==null)b.vt0=r4(opDur+kb.t0);
  const rs=RS.filter(r=>r.beat===id);
  if(rs.length){if(b.shot&&rs.some(r=>r.shot))b.shot.params=Object.assign({},b.shot.params||{},...rs.map(r=>r.shot||{}));
   if(b.crowd&&rs.some(r=>r.crowd))b.crowd.params=Object.assign({},b.crowd.params||{},...rs.map(r=>r.crowd||{}));
   // header patch (e.g. {scrim:true}: QA v6 — scene lettering passing behind the HUD header on a re-shot beat)
   if(rs.some(r=>r.header)&&b.header!==false)b.header=Object.assign({},typeof b.header==='object'?b.header:{},...rs.map(r=>r.header||{}));
   // crowd-vfx (notes-crowd-vfx.md): a re-shot caught beat uses the plain caught-press crowd
   if(id==='caught'&&b.crowd)b.crowd.params={...(b.crowd.params||{}),plain:true};
   b.origin=ref;b.fix=rs.map(r=>r.why).filter(Boolean).join('; ')||'re-shot (v6 accuracy)';}
  else b.reuse=ref;
  return b;});
 const sb=K.beats.find(b=>b.id==='sources'),sItem=(sb?.hud||[]).find(h=>h.c==='sources')||{};
 const endIds=ENDCARD_FACTS.filter(id=>FACTS[id]);
 // qa-rules 5: the sources card lists the union incl. the facts cited only in the shared opening (rules beat footnote)
 const opIds=[...new Set(JSON.stringify(read('_opening.json')).match(/"factIds":\[[^\]]*\]/g)?.flatMap(m=>JSON.parse(m.slice(10)))||[])].filter(id=>FACTS[id]&&!FACTS[id].na);
 const beats=[
  {id:'first-choice',dur:4.5,shot:{key:'card-bg',params:{yaw0:.3}},hud:[clone(FIRST_CHOICE)],header:clone(HEADER_V6),clock:false,bgm:BGM.first,amb:null},
  {id:'true-end',dur:4,shot:{key:'true-end-bg'},hud:[clone(TRUE_END)],header:clone(HEADER_V6),clock:false,bgm:BGM.trueEnd,amb:null},
  {id:'guide',dur:3,shot:{key:'card-bg',params:{yaw0:.9}},hud:[clone(GUIDE)],header:clone(HEADER_V6),clock:false,bgm:BGM.guide,amb:null},
  ...copied,
  {id:'goodbye',dur:8,shot:{key:'card-bg',params:{yaw0:2.2,tone:'dark'}},hud:[clone(GOODBYE)],header:false,clock:false,footnote:false,bgm:BGM.goodbye,amb:null},
  // sources: page footnote off — the card lists every source + its own PLATEAU/OSM credit line (with 16 ids the footnote
  // would repeat the whole list and overflow its 3-line box: recorder 'footnote clipped', integrator 2026-10-27)
  {id:'sources',dur:3.5,shot:{key:'card-bg',params:{yaw0:1.5}},hud:[{c:'sources',compact:true,...(sItem.note?{note:sItem.note}:{}),parodyNote:clone(SOURCES_NOTE),factIds:[]}],header:clone(HEADER_V6),clock:false,footnote:false,bgm:BGM.sources,amb:null,fadeOut:.4},
 ];
 return {id:`v6-${pair}`,episode:'jr',pair,kind:'v6',outcome:'V6',edition:'v6',parts:{over:K.parts.over,clear:K.parts.clear,combined:kid},
  title:clone(K.title),start:clone(K.start),clock:clone(K.clock),choice:clone(K.choice),firstChoice:{prompt:{ja:V.V6_FIRST.prompt},options:clone(FIRST_OPTIONS),picked:'A'},
  beats,lesson:clone(K.lesson),cheat:clone(K.cheat),sources:[...new Set([...(K.sources||[]),...opIds,...endIds])],bgm:K.bgm,amb:K.amb,routes:clone(K.routes||{}),
  generated:'tools/v6_configs.mjs (do not edit by hand: edit the generator / v6/_reshoot.json and re-run --write)'};}

export const v6Path=pair=>path.join(OUTDIR,`${pair}.json`);
export const openingPath=()=>path.join(OUTDIR,'_opening.json');
export const serialize=cfg=>JSON.stringify(cfg,null,1)+'\n';

function main(argv){const write=argv.includes('--write'),check=argv.includes('--check');let rc=0;
 const imp=argv.indexOf('--import-reshoot');
 if(imp>=0){const f=argv[imp+1];const rows=parseReshootTable(fs.readFileSync(f,'utf8'));
  if(!rows){console.error(`no RESHOOT table in ${f}`);return 1;}
  const out={note:`imported from ${path.basename(f)} by tools/v6_configs.mjs --import-reshoot; edit here or re-import`,items:rows};
  console.log(JSON.stringify(out,null,1));if(write){fs.mkdirSync(OUTDIR,{recursive:true});fs.writeFileSync(RESHOOT_FILE,JSON.stringify(out,null,1)+'\n');console.error(`wrote ${path.relative(ROOT,RESHOOT_FILE)} (${rows.length} rows); now run --write`);}
  return 0;}
 const pairs=argv.filter(a=>!a.startsWith('-'));
 const files=[[openingPath(),buildOpening(),'opening']];for(const p of pairs.length?pairs:PAIRS)files.push([v6Path(p),buildV6(p),p]);
 const missing=ENDCARD_FACTS.filter(id=>!FACTS[id]);if(missing.length)console.error(`warning: end-card fact ids not in sources-series.mjs FACTS yet (left out of sources[]): ${missing.join(', ')}`);
 for(const [f,cfg,lab] of files){const s=serialize(cfg);
  if(write){fs.mkdirSync(OUTDIR,{recursive:true});fs.writeFileSync(f,s);}
  const same=fs.existsSync(f)&&fs.readFileSync(f,'utf8')===s;if(check&&!same)rc=1;
  const P=V.buildPart(cfg);
  console.log(`${lab}: ${cfg.beats.length} beats · ${P.duration.toFixed(2)} s (${P.frames} frames) · new: ${cfg.beats.filter(b=>!b.reuse).map(b=>b.id+(b.origin?'(re-shot)':'')).join(', ')} · ${write?'written':same?'up to date':'DIFFERS from '+path.relative(ROOT,f)}`);}
 return rc;}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url))process.exit(main(process.argv.slice(2)));
